```java
package com.company;

import java.util.ArrayList;
import java.util.List;

public class PermutationOfPalindrome {

    private String input;
    private List<String> permutations = new ArrayList<>();

    public PermutationOfPalindrome(String input) {
        this.input = input;
    }

    private String getReverse(String s) {
        StringBuilder sb = new StringBuilder();
        for (int i = s.length() - 1; i >= 0; i--) {
            sb.append(s.charAt(i));
        }
        return sb.toString();
    }

    private List<String> getPermutations(String s) {
        List<String> permutations = new ArrayList<>();
        if (s.length() == 0) {
            permutations.add("");
            return permutations;
        }
        for (int i = 0; i < s.length(); i++) {
            List<String> smallerPermutations = getPermutations(s.substring(0, i) + s.substring(i + 1));
            for (String smallerPermutation : smallerPermutations) {
                permutations.add(s.charAt(i) + smallerPermutation);
            }
        }
        return permutations;
    }

    public List<String> getPermutations() {
        return permutations;
    }

    public boolean isPalindromePermutation() {
        String inputReverse = getReverse(input);
        return permutations.contains(inputReverse);
    }

    public static void main(String[] args) {
        PermutationOfPalindrome permPal1 = new PermutationOfPalindrome("");
        System.out.println(permPal1.getPermutations()); // Expected: []
        System.out.println(permPal1.isPalindromePermutation());  // Expected: false

        PermutationOfPalindrome permPal2 = new PermutationOfPalindrome("racecar");
        System.out.println(permPal2.getPermutations()); // Expected: [racecar]
        System.out.println(permPal2.isPalindromePermutation());  // Expected: true

        PermutationOfPalindrome permPal3 = new PermutationOfPalindrome("level");
        System.out.println(permPal3.getPermutations()); // Expected: [ellev, evel, leve, lelve, elvel, event]
        System.out.println(permPal3.isPalindromePermutation()); // Expected: true

        PermutationOfPalindrome permPal4 = new PermutationOfPalindrome("hello");
        System.out.println(permPal4.getPermutations()); // Expected: [elloh, helol, hlole, hlelo]
        System.out.println(permPal4.isPalindromePermutation()); // Expected: false
    }
}
```

